  CONSTRAINT club_forms_published_by_user_id_not_null NOT NULL published_by_user_id,
  CONSTRAINT club_forms_slug_not_null NOT NULL slug,
  CONSTRAINT club_forms_tenant_id_not_null NOT NULL tenant_id,
