-- Functions
CREATE OR REPLACE FUNCTION public.app_tenant_id()
 RETURNS integer
 LANGUAGE sql
 STABLE
AS $function$ SELECT NULLIF(current_setting('app.tenant_id', true), '')::integer $function$;
CREATE OR REPLACE FUNCTION public.link_account_to_rows()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.deleted_at IS NOT NULL THEN
    UPDATE "attendance" SET user_id = NULL WHERE user_id = NEW.id;
    UPDATE "bookings" SET user_id = NULL WHERE user_id = NEW.id;
    UPDATE "casual_play_profiles" SET user_id = NULL WHERE user_id = NEW.id;
    UPDATE "day_requests" SET user_id = NULL WHERE user_id = NEW.id;
    UPDATE "donations" SET user_id = NULL WHERE user_id = NEW.id;
    UPDATE "jersey_registrations" SET user_id = NULL WHERE user_id = NEW.id;
    UPDATE "memberships" SET user_id = NULL WHERE user_id = NEW.id;
    UPDATE "player_absences" SET user_id = NULL WHERE user_id = NEW.id;
    UPDATE "session_fill_ins" SET user_id = NULL WHERE user_id = NEW.id;
    UPDATE "waitlist" SET user_id = NULL WHERE user_id = NEW.id;
  ELSE
    UPDATE "attendance" SET user_id = NEW.id WHERE user_id IS NULL AND lower(trim(email)) = NEW.email;
    UPDATE "bookings" SET user_id = NEW.id WHERE user_id IS NULL AND lower(trim(email)) = NEW.email;
    UPDATE "casual_play_profiles" SET user_id = NEW.id WHERE user_id IS NULL AND lower(trim(email)) = NEW.email;
    UPDATE "day_requests" SET user_id = NEW.id WHERE user_id IS NULL AND lower(trim(email)) = NEW.email;
    UPDATE "donations" SET user_id = NEW.id WHERE user_id IS NULL AND lower(trim(email)) = NEW.email;
    UPDATE "jersey_registrations" SET user_id = NEW.id WHERE user_id IS NULL AND lower(trim(email)) = NEW.email;
    UPDATE "memberships" SET user_id = NEW.id WHERE user_id IS NULL AND lower(trim(email)) = NEW.email;
    UPDATE "player_absences" SET user_id = NEW.id WHERE user_id IS NULL AND lower(trim(email)) = NEW.email;
    UPDATE "session_fill_ins" SET user_id = NEW.id WHERE user_id IS NULL AND lower(trim(email)) = NEW.email;
    UPDATE "waitlist" SET user_id = NEW.id WHERE user_id IS NULL AND lower(trim(email)) = NEW.email;
  END IF;
  RETURN NULL;
END $function$;
CREATE OR REPLACE FUNCTION public.link_row_to_account()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.user_id IS NULL AND NEW.email IS NOT NULL THEN
      SELECT p.id INTO NEW.user_id FROM players p WHERE p.deleted_at IS NULL AND p.email = lower(trim(NEW.email));
    END IF;
  ELSIF NEW.email IS DISTINCT FROM OLD.email THEN
    NEW.user_id := (SELECT p.id FROM players p WHERE p.deleted_at IS NULL AND p.email = lower(trim(NEW.email)));
  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.moderation_evidence_for_child_safety()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM content_reports r WHERE r.id = NEW.report_id AND r.reason = 'child_safety') THEN
    RAISE EXCEPTION 'moderation_evidence: only a child_safety report keeps evidence' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END $function$;
CREATE OR REPLACE FUNCTION public.player_photos_purpose_is_fixed()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.purpose IS DISTINCT FROM OLD.purpose THEN
    RAISE EXCEPTION 'player_photos.purpose cannot be changed (photo %)', OLD.id USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.players_phone_sealed_follows_plain()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.phone_e164 IS NULL OR (NEW.phone_e164 IS DISTINCT FROM OLD.phone_e164 AND NEW.phone_sealed IS NOT DISTINCT FROM OLD.phone_sealed) THEN
    NEW.phone_sealed := NULL;
    NEW.phone_index := NULL;
    NEW.phone_index_kid := NULL;
  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.shares_social_club(p_a integer, p_b integer)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT EXISTS (SELECT 1 FROM social_clubs_of(p_a) a(club_id) JOIN social_clubs_of(p_b) b(club_id) USING (club_id))
$function$;
CREATE OR REPLACE FUNCTION public.social_clubs_of(p_player_id integer)
 RETURNS SETOF bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT cm.tenant_id::bigint
  FROM club_members cm
  JOIN tenants t ON t.id = cm.tenant_id
  JOIN tenant_modules m ON m.tenant_id = cm.tenant_id
  WHERE cm.user_id = p_player_id AND cm.status = 'active' AND t.status = 'active'
    AND m.module_id = 'social' AND m.enabled
  ORDER BY 1
$function$;

